fun solution(nums: IntArray): Int {
val distinctCount = nums.toSet().size // 요인 1: 서로 다른 종류 수
val pickLimit = nums.size / 2 // 요인 2: 고를 수 있는 최대 개수
return minOf(distinctCount, pickLimit) // 둘 중 더 "제한이 되는" 쪽
}
