class Solution {
fun solution(board: Array<IntArray>, moves: IntArray): Int {
var bag = mutableListOf<Int>()
var answer = 0
var arr = mutableListOf<MutableList<Int>>()
for(i in board.size - 1 downTo 0) {
val ele = mutableListOf<Int>()
for(j in board[i]) {
ele.add(j)
}
arr.add(ele)
}
for(move in moves) {
for(i in arr.size - 1 downTo 0) {
if(arr[i][move - 1] <= 0 ) continue
else {
val last = arr[i][move - 1]
if(bag.isNotEmpty() && bag.last() == last) {
bag.removeLast()
answer += 2
} else bag.add(last)
arr[i][move - 1] = -1
break
}
}
}
return answer
}
}
