2.3. VNode를 실제 DOM으로 변환하기
createElement()
LikeButton()이 반환한 값은 JavaScript 객체이기 때문에 그대로 화면에 표시할 수 없어요.
화면에 표시할 수 있도록 VNode를 실제 DOM으로 변환하는 createElement() 함수를 만들었어요.
export function createElement(vNode) {
// 문자열과 숫자는 텍스트노드로 처리
if (typeof vNode === "string" ||typeof vNode === "number") {
return document.createTextNode(String(vNode));
}
// VNode 객체는 type을 이용해 실제 요소로 만들기
const element = document.createElement(vNode.type);
// Props를 실제 DOM 속성으로 적용
Object.entries(vNode.props ?? {}).forEach(([name, value]) => {
element.setAttribute(name, value);
}
);
// 자식 VNode에도 createElement()를 재귀적으로 호출
vNode.children.forEach((child) => {
element.appendChild(createElement(child));
});
return element;
}
render()
마지막으로 생성한 DOM을 루트 요소에 추가하는 render() 함수를 만들었어요.
// vdom.js
export function render(vNode, container) {
container.appendChild(
createElement(vNode)
);
}
이제 LikeButton()으로 만든 VNode를 실제 화면에 표시할 수 있어요.
// postDetail.js
const likeButtonRoot =
document.getElementById(
"like-button-root"
);
render(
LikeButton(
isLiked,
currentLikeCount,
handleLike
),
likeButtonRoot
);
2.4. 버튼에 이벤트 핸들러 등록하기
좋아요 버튼은 화면에 정상적으로 표시됐지만 버튼을 클릭해도 아무 일도 일어나지 않았어요.
왜냐하면 모든 Props를 setAttribute()로 처리하고 있었기 때문이에요.
element.setAttribute(name, value);
이벤트가 동작하려면 이 함수를 실제 DOM의 이벤트 프로퍼티에 연결해야 해요.
속성 이름이 on으로 시작하고 값이 함수라면 이벤트 핸들러로 판단하도록 코드를 변경했어요.
// vdom.js - createElement()
Object.entries(vNode.props ?? {}).forEach(([name, value]) => {
if(name.startsWith('on') && typeof value === "function"){
element[name.toLowerCase()] = value;
return;
}
element.setAttribute(name, value);
});
VNode의 onClick은 소문자로 변환되어 실제 DOM의 onclick 프로퍼티에 연결돼요.
element.onclick = value;
이제 클릭 이벤트는 정상적으로 동작해요.
하지만 상태가 바뀐 뒤 화면에 새로운 값을 반영하려면 좋아요 버튼 전체를 다시 만들어야 했어요. 이렇게 되면 상태가 바뀔때마다 매번 좋아요 버튼을 새로 만들어서 비효율적이에요.
그래서 다음으로는 Diff 과정을 구현하고, 적용해봤어요
3. 좋아요 버튼에 Diff 적용하기
상태가 변경될 때마다 좋아요 버튼 전체를 교체하는 대신, 이전 VNode와 새로운 VNode를 비교해 변경된 부분만 실제 DOM에 반영해보기로 했어요.
3.1. updateElement()
diff 구현을 위해 노드 비교를 담당하는 updateElement() 함수를 만들었어요.
먼저 두 VNode를 비교하면서 발생할 수 있는 상황을 나눠봤어요.
새로운 VNode에서 노드가 사라진 경우
이전 VNode에는 있지만 새로운 VNode에는 없다면 실제 DOM에서도 제거해요.
if (!newNode && oldNode) {
return parent.removeChild(
parent.childNodes[index]
);
}
새로운 노드가 추가된 경우
새로운 VNode에만 노드가 존재한다면 실제 DOM으로 변환해 추가해요.
if (newNode && !oldNode) {
return parent.appendChild(
createElement(newNode)
);
}
두 노드가 모두 문자열인 경우
두 노드가 문자열이라면 값을 비교하고, 값이 달라진 경우에만 텍스트 노드를 교체해요.
if (
typeof newNode === "string" &&
typeof oldNode === "string"
) {
if (newNode === oldNode) {
return;
}
return parent.replaceChild(
createElement(newNode),
parent.childNodes[index]
);
}
노드의 JavaScript 타입이 다른 경우
한쪽이 텍스트이고 다른 쪽이 VNode 객체라면 기존 DOM을 버리고 새로 만들어요
if (
typeof newNode !== typeof oldNode
) {
return parent.replaceChild(
createElement(newNode),
parent.childNodes[index]
);
}
같은 종류의 노드라면 속성을 비교해요
두 노드가 같은 종류라면 기존 DOM을 유지하고 속성을 비교했어요.
updateAttributes(
parent.childNodes[index],
newNode.props ?? {},
oldNode.props ?? {}
);
function updateAttributes(
target,
newProps,
oldProps
) {
for (
const [attribute, value]
of Object.entries(newProps)
) {
if (
oldProps[attribute] === value
) {
continue;
}
target.setAttribute(
attribute,
value
);
}
}
현재 노드의 비교가 끝나면 자식 노드에도 같은 비교 과정을 재귀적으로 적용했어요.
const maxLength = Math.max(
newNode.children.length,
oldNode.children.length
);
for (let i = 0; i < maxLength; i++) {
updateElement(
parent.childNodes[index],
newNode.children[i],
oldNode.children[i]
);
}
3.2. 좋아요 버튼에 적용하기
기본적인 Diff를 구현한 뒤 좋아요 버튼에 적용해봤어요.
// postDetail.js
function updateLikeButtonState() {
const oldState = {
isLiked: !isLiked,
currentLikeCount: isLiked
? currentLikeCount - 1
: currentLikeCount + 1,
};
const oldNode = LikeButton(
oldState.isLiked,
oldState.currentLikeCount,
handleLike
);
const newNode = LikeButton(
isLiked,
currentLikeCount,
handleLike
);
updateElement(
likeButtonRoot,
newNode,
oldNode
);
}
그런데 Diff를 적용하자 새로운 문제들이 나타나기 시작했어요.
4. 디버깅... 😱
4.1. 좋아요 숫자가 엉뚱한 위치로 갔어요
render()로 버튼 전체를 생성했을 때는 숫자가 정상적인 위치에 표시됐어요.
하지만 updateElement()를 적용하자 버튼을 클릭하면 좋아요 숫자가 엉뚱한 위치에 나타났어요.
자식 노드의 Diff 과정을 확인해보니 현재 자식의 인덱스를 재귀 호출에 전달하지 않고 있었어요.
updateElement(
parent.childNodes[index],
newNode.children[i],
oldNode.children[i]
);
updateElement()의 index 기본값은 0이었어요. 자식의 인덱스를 전달하지 않으니 모든 자식 비교가 첫 번째 DOM 노드를 대상으로 수행되고 있었어요.
현재 자식의 인덱스인 i를 전달하도록 수정했어요.
updateElement(
parent.childNodes[index],
newNode.children[i],
oldNode.children[i],
i
);
또한 텍스트 노드 비교에서는 문자열만 처리하고 있었어요.
typeof newNode === "string"
하지만 좋아요 개수는 숫자이므로 숫자도 텍스트 노드와 같은 방식으로 처리해야 했어요.
const isTextNode = (node) =>
typeof node === "string" ||
typeof node === "number";
두 문제를 수정하니 좋아요 버튼을 클릭해도 숫자가 정상적인 위치에 표시됐어요.
4.2. 좋아요가 0이면 숫자도 사라져요
그런데 좋아요 개수가 0이면 숫자가 화면에 나타나지 않았어요.
원인은 노드의 존재 여부를 판단하는 조건이었어요.
if (!newNode && oldNode) {
// 기존 노드를 제거해요.
}
JavaScript에서 숫자 0은 falsy 값이에요. 값이 존재하는 텍스트 노드인데도 새로운 노드가 없다고 판단하고 있었어요.
노드가 없다는 의미를 0이 아니라 null 또는 undefined로 한정해야 했어요.
if (newNode == null && oldNode != null) {
return parent.removeChild(parent.childNodes[index]);
}
if (newNode != null &&oldNode == null) {
return parent.appendChild(createElement(newNode));
}
조건을 수정한 뒤에는 좋아요 개수가 0일 때도 정상적으로 표시됐어요.
4.3. 이전 상태를 추측해도 될까요?
좋아요 버튼은 정상적으로 동작하기 시작했지만, 현재 상태의 반대 값을 이용해 이전 VNode를 만드는 방식이 마음에 걸렸어요.
const oldState = {
isLiked: !isLiked,
currentLikeCount: isLiked
? currentLikeCount - 1
: currentLikeCount + 1,
};
이 값은 실제로 이전 렌더링에 사용했던 상태가 아니에요. 현재 상태를 기준으로 이전 값을 추측한 것에 불과해요.
초기 상태가 예상과 다르거나 서버에서 다른 값이 응답되면 실제 DOM과 비교에 사용하는 oldNode가 일치하지 않을 수 있어요.
Diff가 올바르게 동작하려면 이전 VNode도 실제 렌더링 결과와 일치해야 해요.
그래서 현재 화면에 반영된 VNode를 별도로 저장하기로 했어요.
let currentLikeNode;
상태가 변경되면 새로운 VNode를 생성하고, 저장해둔 currentLikeNode와 비교했어요.
function updateLikeButtonState() {
const newNode = LikeButton(
isLiked,
currentLikeCount,
handleLike
);
updateElement(likeButtonRoot,newNode,currentLikeNode);
currentLikeNode = newNode;
}
이 구조를 만들면서 React에서 상태가 변경되면 새로운 렌더링 결과를 만들고, 이전 결과와 비교한다는 흐름을 조금 더 구체적으로 이해할 수 있었어요.
5. 마무리
좋아요 버튼을 통해 VNode 생성, 실제 DOM 변환, 이벤트 연결, 상태 변경과 Diff까지 확인했어요!
하지만 좋아요 버튼은 자식의 개수와 구조가 고정된 UI예요. 노드가 여러 개 추가되거나 삭제되고, 순서가 바뀌는 더 복잡한 상황까지 확인하기에는 부족하다는 생각이 들었어요.
